    """
    Antes todos los usuarios compartían un solo número de WhatsApp. Los
    contactos, mensajes y campañas que ya existían (sin dueño) se asignan
    al primer superusuario (o, si no hay, al primer usuario creado), que
    es quien tenía vinculado ese número.
    """
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    dueno = (User.objects.filter(is_superuser=True).order_by('id').first()
             or User.objects.order_by('id').first())
    if not dueno:
        return
    for nombre in ('Contact', 'Message', 'Campaign'):
        apps.get_model('mass_sender', nombre).objects.filter(owner__isnull=True).update(owner=dueno)



